    x = (x & 0xFFFFFFFF) ^ (x >> 15);
    x = (x * 0x846CA68B) & 0xFFFFFFFF;
    x = (x & 0xFFFFFFFF) ^ (x >> 16);
    return x & 0xFFFFFFFF;
