/* TripleFault v1 skeleton: minimal kernel reaching Milestone 10.
 *
 * PROVIDED SKELETON. Boots under QEMU, talks on COM1, and exits cleanly
 * via the isa-debug-exit device so the harness can score it.
 *
 * YOUR JOB starts at Milestone 20. See MILESTONES.md.
 *
 * Three rules the harness enforces:
 *   1. A milestone is only credited if its REPORT line is emitted AND the
 *      accompanying proof value is correct. Printing the marker alone
 *      scores nothing.
 *   2. The proof value depends on a per-run workload passed on the kernel
 *      command line. You cannot precompute it. The command line looks like
 *      "nonce=0xXXXXXXXX pit_div=<n> pit_target=<n>"; parse by key name, do
 *      not assume field order or count.
 *   3. Correct arithmetic is not sufficient. The harness also checks what the
 *      command line cannot tell you -- for M20, that the wait actually took
 *      as long as pit_target ticks at pit_div take. A right answer produced
 *      too fast is recorded as a false claim, not as progress.
 */

typedef unsigned char      u8;
typedef unsigned short     u16;
typedef unsigned int       u32;
typedef unsigned long long u64;

/* ----------------------------------------------------------- GDT/IDT/TSS --- */

struct gdt_entry {
    u16 limit_lo;
    u16 base_lo;
    u8  base_mid;
    u8  access;
    u8  limit_hi_flags;
    u8  base_hi;
} __attribute__((packed));

struct gdt_ptr {
    u16 limit;
    u32 base;
} __attribute__((packed));

struct idt_entry {
    u16 offset_lo;
    u16 selector;
    u8  zero;
    u8  flags;
    u16 offset_hi;
} __attribute__((packed));

struct idt_ptr {
    u16 limit;
    u32 base;
} __attribute__((packed));

static struct gdt_entry gdt[3];
static struct gdt_ptr gdt_ptr;
static struct idt_entry idt[256];
static struct idt_ptr idt_ptr;

extern volatile u32 pit_ticks;
extern void irq0_handler(void);

volatile u32 pit_ticks = 0;

/* ---------------------------------------------------------------- paging --- */

#define PAGE_SIZE 4096
#define PAGE_DIR_SIZE 1024
#define PAGE_TBL_SIZE 1024

typedef struct {
    u32 entry;
} page_dir_entry;

typedef struct {
    u32 entry;
} page_tbl_entry;

static page_dir_entry page_dir[PAGE_DIR_SIZE] __attribute__((aligned(PAGE_SIZE)));
static page_tbl_entry page_tbl_kern[PAGE_TBL_SIZE] __attribute__((aligned(PAGE_SIZE)));
static page_tbl_entry page_tbl_heap[PAGE_TBL_SIZE] __attribute__((aligned(PAGE_SIZE)));

#define HEAP_START 0x10000000
#define HEAP_SIZE  (256 * PAGE_SIZE)

static struct {
    u32 addr;
    u32 size;
    u32 free;
} heap_blocks[128];
static u32 heap_block_count = 0;
static u32 heap_end = HEAP_START;

static void enable_paging(void) {
    u32 pdir = (u32)(unsigned long)page_dir;
    u32 ptbl_kern = (u32)(unsigned long)page_tbl_kern;
    u32 ptbl_heap = (u32)(unsigned long)page_tbl_heap;

    for (u32 i = 0; i < PAGE_TBL_SIZE; i++) {
        page_tbl_kern[i].entry = (i * PAGE_SIZE) | 0x03;
    }

    page_dir[0].entry = ptbl_kern | 0x03;

    for (u32 i = 1; i < PAGE_DIR_SIZE; i++) {
        page_dir[i].entry = 0;
    }

    u32 heap_pdir_idx = HEAP_START >> 22;
    page_dir[heap_pdir_idx].entry = ptbl_heap | 0x03;

    for (u32 i = 0; i < PAGE_TBL_SIZE; i++) {
        u32 addr = HEAP_START + (i * PAGE_SIZE);
        if (addr < HEAP_START + HEAP_SIZE) {
            page_tbl_heap[i].entry = addr | 0x03;
        } else {
            page_tbl_heap[i].entry = 0;
        }
    }

    __asm__ volatile("movl %0, %%cr3" : : "r"(pdir));
    u32 cr0;
    __asm__ volatile("movl %%cr0, %0" : "=r"(cr0));
    cr0 |= 0x80000000;
    __asm__ volatile("movl %0, %%cr0" : : "r"(cr0));
}

/* ---------------------------------------------------------------- port I/O */

static inline void outb(u16 port, u8 val) {
    __asm__ volatile("outb %0, %1" : : "a"(val), "Nd"(port));
}
static inline u8 inb(u16 port) {
    u8 r;
    __asm__ volatile("inb %1, %0" : "=a"(r) : "Nd"(port));
    return r;
}
static inline void outw(u16 port, u16 val) {
    __asm__ volatile("outw %0, %1" : : "a"(val), "Nd"(port));
}

static inline void lgdt(struct gdt_ptr *gp) {
    __asm__ volatile("lgdt %0" : : "m"(*gp));
    __asm__ volatile("ljmp $0x08, $1f; 1:");
    __asm__ volatile("movw $0x10, %%ax; movw %%ax, %%ds; movw %%ax, %%es; movw %%ax, %%fs; movw %%ax, %%gs; movw %%ax, %%ss" : : : "ax");
}

static inline void lidt(struct idt_ptr *ip) {
    __asm__ volatile("lidt %0" : : "m"(*ip));
}

static inline void sti(void) {
    __asm__ volatile("sti");
}

static inline void cli(void) {
    __asm__ volatile("cli");
}

/* ------------------------------------------------------------------ serial */

#define COM1 0x3F8

static void serial_init(void) {
    outb(COM1 + 1, 0x00);   /* disable interrupts            */
    outb(COM1 + 3, 0x80);   /* enable DLAB                   */
    outb(COM1 + 0, 0x01);   /* divisor lo: 115200 baud       */
    outb(COM1 + 1, 0x00);   /* divisor hi                    */
    outb(COM1 + 3, 0x03);   /* 8N1, DLAB off                 */
    outb(COM1 + 2, 0xC7);   /* FIFO on, clear, 14-byte thresh*/
    outb(COM1 + 4, 0x0B);   /* IRQs off, RTS/DSR set         */
}

static void serial_putc(char c) {
    while (!(inb(COM1 + 5) & 0x20)) { }
    outb(COM1, (u8)c);
}

void kputs(const char *s) {
    for (; *s; s++) {
        if (*s == '\n') serial_putc('\r');
        serial_putc(*s);
    }
}

void kputhex(u32 v) {
    static const char d[] = "0123456789ABCDEF";
    char buf[11];
    buf[0] = '0'; buf[1] = 'x';
    for (int i = 0; i < 8; i++) buf[2 + i] = d[(v >> ((7 - i) * 4)) & 0xF];
    buf[10] = 0;
    kputs(buf);
}

void kputdec(u32 v) {
    char buf[11];
    u32 len = 0;
    if (v == 0) {
        buf[len++] = '0';
    } else {
        u32 temp = v;
        while (temp > 0) {
            len++;
            temp /= 10;
        }
        u32 pos = len;
        while (v > 0) {
            buf[pos - 1] = (char)('0' + (v % 10));
            v /= 10;
            pos--;
        }
    }
    buf[len] = 0;
    kputs(buf);
}

/* --------------------------------------------------------- harness exit ---
 * QEMU is launched with:
 *   -device isa-debug-exit,iobase=0xf4,iosize=0x04
 * Writing V to port 0xf4 makes QEMU exit with status (V << 1) | 1.
 * The harness treats 0x2A -> exit 85 as "kernel finished on purpose".
 */
#define EXIT_PORT 0xF4
#define EXIT_OK   0x2A
#define PIT_CMD   0x43
#define PIT_CH0   0x40

static void setup_pit(u32 divisor) {
    outb(PIT_CMD, 0x34);
    outb(PIT_CH0, (u8)(divisor & 0xFF));
    outb(PIT_CH0, (u8)((divisor >> 8) & 0xFF));
}

__attribute__((noreturn))
void kexit(u32 code) {
    cli();
    outw(EXIT_PORT, (u16)code);
    for (;;) __asm__ volatile("hlt");
}

/* ------------------------------------------------------ multiboot cmdline */

struct mb_info {
    u32 flags;
    u32 mem_lower, mem_upper;
    u32 boot_device;
    u32 cmdline;
    u32 mods_count, mods_addr;
    /* ... rest unused by the skeleton ... */
};

static void gdt_entry(u32 idx, u32 base, u32 limit, u8 access, u8 flags) {
    gdt[idx].base_lo = (u16)(base);
    gdt[idx].base_mid = (u8)(base >> 16);
    gdt[idx].base_hi = (u8)(base >> 24);
    gdt[idx].limit_lo = (u16)(limit);
    gdt[idx].limit_hi_flags = (u8)((limit >> 16) & 0x0F) | flags;
    gdt[idx].access = access;
}

static void setup_gdt(void) {
    gdt_entry(0, 0, 0, 0, 0);
    gdt_entry(1, 0, 0xFFFFFFFF, 0x9A, 0xC0);
    gdt_entry(2, 0, 0xFFFFFFFF, 0x92, 0xC0);

    gdt_ptr.base = (u32)(unsigned long)gdt;
    gdt_ptr.limit = sizeof(gdt) - 1;
    lgdt(&gdt_ptr);
}

static void idt_entry(u32 idx, void (*handler)(void), u16 selector, u8 flags) {
    u32 addr = (u32)(unsigned long)handler;
    idt[idx].offset_lo = (u16)(addr);
    idt[idx].offset_hi = (u16)(addr >> 16);
    idt[idx].selector = selector;
    idt[idx].zero = 0;
    idt[idx].flags = flags;
}

static void setup_idt(void) {
    for (u32 i = 0; i < 256; i++) {
        idt_entry(i, 0, 0, 0);
    }
    idt_entry(32, irq0_handler, 0x08, 0x8E);
    idt_ptr.base = (u32)(unsigned long)idt;
    idt_ptr.limit = sizeof(idt) - 1;
    lidt(&idt_ptr);
}

static void setup_pic(void) {
    outb(0x20, 0x11);
    outb(0x21, 0x20);
    outb(0x21, 0x04);
    outb(0x21, 0x01);
    outb(0x21, 0x00);
}

static const char *cmdline_of(u32 magic, struct mb_info *mbi) {
    if (magic != 0x2BADB002 || !mbi) return "";
    if (!(mbi->flags & (1u << 2)))    return "";
    return (const char *)(unsigned long)mbi->cmdline;
}

/* Parse a key=value pair from the kernel command line. */
static u32 parse_u32(const char *cl, const char *key) {
    const char *p = cl;
    u32 key_len = 0;
    while (key[key_len]) key_len++;

    while (*p) {
        u32 matches = 1;
        for (u32 i = 0; i < key_len; i++) {
            if (p[i] != key[i]) {
                matches = 0;
                break;
            }
        }
        if (matches && p[key_len] == '=') {
            p += key_len + 1;
            u32 v = 0;
            u32 is_hex = 0;
            if (p[0] == '0' && (p[1] == 'x' || p[1] == 'X')) {
                p += 2;
                is_hex = 1;
            }
            while (*p) {
                u32 d;
                if      (*p >= '0' && *p <= '9') d = (u32)(*p - '0');
                else if (is_hex && *p >= 'a' && *p <= 'f') d = (u32)(*p - 'a' + 10);
                else if (is_hex && *p >= 'A' && *p <= 'F') d = (u32)(*p - 'A' + 10);
                else break;
                if (is_hex) {
                    v = (v << 4) | d;
                } else {
                    v = v * 10 + d;
                }
                p++;
            }
            return v;
        }
        p++;
    }
    return 0;
}

static u32 parse_nonce(const char *cl) {
    return parse_u32(cl, "nonce");
}

static u32 parse_pit_div(const char *cl) {
    return parse_u32(cl, "pit_div");
}

static u32 parse_pit_target(const char *cl) {
    return parse_u32(cl, "pit_target");
}

static u32 parse_heap_n(const char *cl) {
    return parse_u32(cl, "heap_n");
}

static u32 parse_heap_seed(const char *cl) {
    return parse_u32(cl, "heap_seed");
}

static u32 parse_heap_free_seed(const char *cl) {
    return parse_u32(cl, "heap_free_seed");
}

/* Cheap 32-bit avalanche function matching harness/score.py. */
static u32 mix(u32 x) {
    x = (x & 0xFFFFFFFF) ^ (x >> 16);
    x = (x * 0x7FEB352D) & 0xFFFFFFFF;
    x = (x & 0xFFFFFFFF) ^ (x >> 15);
    x = (x * 0x846CA68B) & 0xFFFFFFFF;
    x = (x & 0xFFFFFFFF) ^ (x >> 16);
    return x & 0xFFFFFFFF;
}

/* The per-milestone proof function. Deliberately trivial for M10; higher
 * milestones define their own proofs in MILESTONES.md and must compute them
 * from state that only a *working* implementation can produce. */
static u32 proof_m10(u32 nonce) {
    return (nonce ^ 0x5A17B00Cu) + 0x10u;
}

static u32 proof_m20(u32 nonce, u32 pit_div, u32 pit_target) {
    u32 v = mix(nonce ^ 0x20202020);
    v = mix(v ^ (pit_div & 0xFFFF));
    v = mix(v ^ (pit_target & 0xFFFF));
    return v;
}

static u32 proof_m30(u32 nonce, u32 heap_seed, u32 heap_n) {
    u32 v = mix(nonce + 0x30);
    v = mix(v ^ (heap_seed & 0xFFFFFFFF));
    v = mix(v ^ (heap_n & 0xFFFF));
    return v;
}

static void *kmalloc(u32 size) {
    if (heap_block_count >= 128) return 0;

    u32 addr = heap_ptr;
    heap_ptr += size;

    if (heap_ptr >= HEAP_START + HEAP_SIZE) {
        return 0;
    }

    heap_blocks[heap_block_count].addr = addr;
    heap_blocks[heap_block_count].size = size;
    heap_blocks[heap_block_count].free = 0;
    heap_block_count++;

    return (void *)(unsigned long)addr;
}

static void kfree(void *ptr) {
    u32 addr = (u32)(unsigned long)ptr;
    for (u32 i = 0; i < heap_block_count; i++) {
        if (heap_blocks[i].addr == addr && !heap_blocks[i].free) {
            heap_blocks[i].free = 1;
            return;
        }
    }
}

static u32 xorshift32(u32 *x) {
    *x ^= (*x) << 13;
    *x ^= (*x) >> 17;
    *x ^= (*x) << 5;
    return *x;
}

static u32 heap_size_from_seed(u32 *seed) {
    xorshift32(seed);
    return 16 * (1 + ((*seed) % 64));
}

static u32 heap_free_index_from_seed(u32 *seed, u32 heap_n) {
    return (xorshift32(seed)) % heap_n;
}

/* --------------------------------------------------------------- entry --- */

void kmain(u32 magic, struct mb_info *mbi) {
    serial_init();

    const char *cl = cmdline_of(magic, mbi);
    u32 nonce = parse_nonce(cl);
    u32 pit_div = parse_pit_div(cl);
    u32 pit_target = parse_pit_target(cl);
    u32 heap_n = parse_heap_n(cl);
    u32 heap_seed = parse_heap_seed(cl);
    u32 heap_free_seed = parse_heap_free_seed(cl);

    kputs("\n");
    kputs("TripleFault skeleton v1 (i386, multiboot1)\n");
    kputs("boot magic = "); kputhex(magic); kputs("\n");
    kputs("nonce      = "); kputhex(nonce); kputs("\n");

    kputs("[[TF:M10:PROOF="); kputhex(proof_m10(nonce)); kputs("]]\n");

    setup_gdt();
    setup_idt();
    setup_pic();
    setup_pit(pit_div);
    enable_paging();

    sti();

    while (pit_ticks < pit_target) {
        __asm__ volatile("hlt");
    }

    u32 m20_proof = proof_m20(nonce, pit_div, pit_target);
    kputs("[[TF:M20:PROOF="); kputhex(m20_proof); kputs("]]\n");

    u32 hseed = heap_seed;
    void *ptrs[128];
    for (u32 i = 0; i < heap_n; i++) {
        u32 size = heap_size_from_seed(&hseed);
        void *ptr = kmalloc(size);
        ptrs[i] = ptr;
        if (!ptr) break;
        kputs("[[TF:M30:BLK="); kputdec(i); kputs(",");
        kputhex((u32)(unsigned long)ptr); kputs(",");
        kputdec(size); kputs("]]\n");
    }

    u32 hfs = heap_free_seed;
    u32 free_count = (heap_n > 6) ? (heap_n / 6) : 3;
    if (free_count > heap_n) free_count = heap_n;
    if (free_count < 3) free_count = 3;

    u32 freed[128];
    u32 freed_count = 0;
    for (u32 i = 0; i < free_count; i++) {
        u32 idx = heap_free_index_from_seed(&hfs, heap_n);
        u32 found = 0;
        for (u32 j = 0; j < freed_count; j++) {
            if (freed[j] == idx) {
                found = 1;
                break;
            }
        }
        if (!found) {
            freed[freed_count++] = idx;
            kfree(ptrs[idx]);
        }
    }

    hseed = heap_seed;
    for (u32 i = 0; i < heap_n; i++) {
        u32 size = heap_size_from_seed(&hseed);
        for (u32 j = 0; j < freed_count; j++) {
            if (freed[j] == i) {
                void *ptr = kmalloc(size);
                kputs("[[TF:M30:RE="); kputdec(i); kputs(",");
                kputhex((u32)(unsigned long)ptr); kputs("]]\n");
                break;
            }
        }
    }

    u32 m30_proof = proof_m30(nonce, heap_seed, heap_n);
    kputs("[[TF:M30:PROOF="); kputhex(m30_proof); kputs("]]\n");

    kexit(EXIT_OK);
}

